import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import test from 'node:test';

import {
  headingSlugs,
  malformedFrontmatterLines,
  readDoc,
  relativeLinks,
  resolveDocPath,
} from './helpers-docs-links.mjs';

const repoRoot = fileURLToPath(new URL('..', import.meta.url));
const docsRoot = join(repoRoot, 'docs');

// Directories sidebars.js renders as `{type: 'autogenerated', dirName: ...}`.
// Every doc in one of these becomes a sidebar entry, which is labelled from
// frontmatter `title` when present. The list is derived from sidebars.js
// rather than restated here so a sidebar added there cannot silently escape
// the title contract.
const sidebars = (await import('../sidebars.js')).default;

const AUTOGENERATED_SIDEBAR_DIRS = [
  ...new Set(
    Object.values(sidebars)
      .flat()
      .filter((entry) => entry?.type === 'autogenerated')
      .map((entry) => entry.dirName),
  ),
].sort();

function walk(dir) {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = join(dir, entry.name);
    return entry.isDirectory() ? walk(full) : [full];
  });
}

const docs = walk(docsRoot)
  .filter((file) => /\.mdx?$/.test(file))
  .sort();

test('the docs/ tree contains documents to check', () => {
  assert.ok(
    docs.length > 0,
    'expected docs/ to contain at least one .md or .mdx file',
  );
});

test('every relative doc-to-doc link resolves to a file on disk', () => {
  const broken = [];
  for (const file of docs) {
    const { body } = readDoc(file);
    for (const href of relativeLinks(body)) {
      const [path] = href.split('#');
      if (!path) continue;
      const target = resolveDocPath(resolve(dirname(file), path));
      if (!target) {
        broken.push(`${relative(repoRoot, file)} -> ${href}`);
      }
    }
  }
  assert.deepEqual(
    broken,
    [],
    `relative links in docs/ must point at files that exist; onBrokenMarkdownLinks is 'warn', so the site build will not catch these`,
  );
});

test('every link fragment matches a heading in its target document', () => {
  const broken = [];
  for (const file of docs) {
    const { body } = readDoc(file);
    for (const href of relativeLinks(body)) {
      const [path, fragment] = href.split('#');
      if (!fragment) continue;
      const target = path ? resolveDocPath(resolve(dirname(file), path)) : file;
      if (!target) continue; // Already reported by the resolution test.
      const slugs = headingSlugs(readDoc(target).body);
      if (!slugs.includes(fragment.toLowerCase())) {
        broken.push(`${relative(repoRoot, file)} -> ${href}`);
      }
    }
  }
  assert.deepEqual(
    broken,
    [],
    'link fragments in docs/ must match a heading in the document they point at',
  );
});

test('every frontmatter fence that opens is terminated', () => {
  const unterminated = docs.filter((file) => {
    const raw = readFileSync(file, 'utf8');
    if (!/^---\r?\n/.test(raw)) return false;
    return !/^---\r?\n[\s\S]*?\r?\n---/.test(raw);
  });
  assert.deepEqual(
    unterminated.map((file) => relative(repoRoot, file)),
    [],
    'a doc that opens a --- frontmatter fence must close it, or Docusaurus renders the metadata as body text',
  );
});

test('frontmatter keys are parseable key: value pairs', () => {
  const malformed = [];
  for (const file of docs) {
    const { frontmatter } = readDoc(file);
    if (frontmatter === null) continue;
    const lines = malformedFrontmatterLines(frontmatter);
    if (lines === null) {
      malformed.push(relative(repoRoot, file));
      continue;
    }
    for (const line of lines) {
      malformed.push(`${relative(repoRoot, file)}: ${line}`);
    }
  }
  assert.deepEqual(malformed, [], 'docs/ frontmatter must be key: value pairs');
});

test('docs in autogenerated sidebar directories declare a title', () => {
  assert.ok(
    AUTOGENERATED_SIDEBAR_DIRS.length > 0,
    'sidebars.js must declare at least one autogenerated sidebar, otherwise this contract asserts nothing',
  );
  const untitled = [];
  for (const dir of AUTOGENERATED_SIDEBAR_DIRS) {
    const dirDocs = docs.filter((file) =>
      relative(docsRoot, file).startsWith(`${dir}/`),
    );
    assert.ok(
      dirDocs.length > 0,
      `sidebars.js autogenerates a sidebar from docs/${dir}, which must contain documents`,
    );
    for (const file of dirDocs) {
      const { frontmatter } = readDoc(file);
      if (frontmatter === null || !/^title:\s*\S/m.test(frontmatter)) {
        untitled.push(relative(repoRoot, file));
      }
    }
  }
  assert.deepEqual(
    untitled,
    [],
    'docs under an autogenerated sidebar need a frontmatter title, otherwise the sidebar label falls back to the filename',
  );
});

// Docusaurus compiles `![text](src)` through its own transformImage remark
// plugin, which HTML-escapes the alt string while building the JSX attribute
// (@docusaurus/mdx-loader, lib/remark/transformImage). The renderer escapes
// that attribute a second time, so an authored `&` reaches the reader as the
// literal five characters `&amp;`: a screen reader spells the entity out, and
// the browser paints it in place of an image that fails to load. That is how
// /architectures/swisscom-kubernetes-service came to announce "a combination
// of CNIP &amp; SKP deliverables" while the build, the link check and the
// accessibility lane -- which read heading order and contrast, not the text of
// an alt string -- all stayed green.
//
// Architecture pages arrive from the submission-issue importer carrying the
// submitter's prose, and cleanMarkdown() rewrites image destinations only; it
// never reads alt text. So this is the gate. Only the brackets are read: the
// same characters in a destination are never announced.
const DOUBLE_ESCAPED_ALT = /!\[[^\]]*["&<>][^\]]*\]/g;

function doubleEscapedAlts(file, markdown) {
  return [...markdown.matchAll(DOUBLE_ESCAPED_ALT)].map(
    (match) => `${relative(repoRoot, file)}: ${match[0]}`,
  );
}

test('alt text the build would double-escape is reported, and nothing else', () => {
  const sample = join(docsRoot, 'sample.md');
  assert.deepEqual(
    doubleEscapedAlts(
      sample,
      [
        '![CNIP & SKP deliverables](./images/d.png)',
        '![CNIP and SKP deliverables](./images/d.png)',
        '![Diagram](./images/d.png?a=1&b=2)',
      ].join('\n\n'),
    ),
    ['docs/sample.md: ![CNIP & SKP deliverables]'],
  );
});

test('no image alt text is double-escaped on the way to the reader', () => {
  const offenders = docs.flatMap((file) =>
    doubleEscapedAlts(file, readFileSync(file, 'utf8')),
  );
  assert.deepEqual(
    offenders,
    [],
    'these alt strings reach the reader with the character spelled out as an ' +
      'HTML entity; write it as a word ("and", "less than", "greater than") ' +
      `or drop it:\n  ${offenders.join('\n  ')}`,
  );
});
